import boto3

session = boto3.Session(
    aws_access_key_id="REDACTED",
    aws_secret_access_key="REDACTED"
)

regions = ["ap-south-1", "us-west-2", "eu-central-1", "us-east-2"]

for r in regions:
    ec2 = session.client("ec2", region_name=r)
    try:
        # DryRun=True tests permissions and PendingVerification without launching an instance
        ec2.run_instances(
            ImageId="ami-0c7217cdde317cfec" if "us-east" in r else "ami-placeholder",
            InstanceType="t2.micro",
            MinCount=1,
            MaxCount=1,
            DryRun=True
        )
    except Exception as e:
        err = str(e)
        if "DryRunOperation" in err:
            print(f"Region {r}: READY (DryRun passed!)")
        elif "PendingVerification" in err:
            print(f"Region {r}: PendingVerification (new AWS account check)")
        elif "InvalidAMIID" in err:
            print(f"Region {r}: AMI invalid, but PendingVerification was NOT triggered! May be active.")
        else:
            print(f"Region {r}: {err[:120]}")

import boto3

session = boto3.Session(
    aws_access_key_id="REDACTED",
    aws_secret_access_key="REDACTED"
)

for reg in ["ap-south-1", "us-east-2", "us-west-2"]:
    ssm = session.client("ssm", region_name=reg)
    ec2 = session.client("ec2", region_name=reg)
    try:
        param = ssm.get_parameter(Name="/aws/service/canonical/ubuntu/server/22.04/stable/current/amd64/hvm/ebs-gp2/ami-id")
        ami = param["Parameter"]["Value"]
        ec2.run_instances(
            ImageId=ami,
            InstanceType="t3.medium",
            MinCount=1,
            MaxCount=1,
            DryRun=True
        )
    except Exception as e:
        err = str(e)
        if "DryRunOperation" in err:
            print(f"Region {reg}: FULLY AUTHORIZED AND READY! (DryRun passed with AMI {ami})")
        elif "PendingVerification" in err:
            print(f"Region {reg}: PendingVerification")
        else:
            print(f"Region {reg}: {err[:140]}")

