25: def parse_module_ports(rtl: str) -> Dict[str, Any]:
26:     """Extract module name, parameter WIDTH, and ports from Verilog RTL."""
27:     m = re.search(r"module\s+(\w+)\s*(?:#\s*\((.*?)\))?\s*\((.*?)\)\s*;", rtl, re.S)
28:     if not m:
29:         return {"name": None, "width": 4, "ports": []}
30:     name = m.group(1)
31:     params = m.group(2) or ""
32:     portlist = m.group(3)
33:     width = 4
34:     wm = re.search(r"parameter\s+WIDTH\s*=\s*(\d+)", params)
35:     if wm:
36:         width = int(wm.group(1))
37:     ports = []
38:     for pm in re.finditer(r"(input|output|inout)\s+(wire|reg)?\s*(\[[^\]]+\])?\s*(\w+)", portlist):
39:         direction, _, width_decl, pname = pm.groups()
40:         ports.append({"name": pname, "direction": direction, "width": width_decl or ""})
41:     return {"name": name, "width": width, "ports": ports}
